from dataclasses import dataclass


@dataclass
class Settings:
    title: str


class BasePlot:
    def __init__(self, settings: Settings) -> None:
        self.settings = settings

    def plot(self, rows: list[str]) -> None:
        self.build(rows)

    def build(self, rows: list[str]) -> None:
        raise NotImplementedError


class LinePlot(BasePlot):
    def build(self, rows: list[str]) -> None:
        print(self.settings.title, rows)


class BarPlot(BasePlot):
    def build(self, rows: list[str]) -> None:
        print(rows)
